import path from 'node:path';
import { afterAll, afterEach, beforeAll, describe, expect, it } from 'vitest';
import { CODES, type Code } from '../../src/lib/case-package/codes.ts';
import { importCandidate, type ImportResult } from '../../src/lib/case-package/index.ts';
import type { Limits } from '../../src/lib/case-package/limits.ts';
import { classifyLink } from '../../src/lib/case-package/links.ts';
import { contentContradictsType, servePolicy } from '../../src/lib/case-package/media.ts';
import { checkRelPath } from '../../src/lib/case-package/paths.ts';
import { displayFilename, displayText, documentRoute, exportCell, isSafeAppHref, renderNarrative, safeExternalHref } from '../../src/lib/case-package/render.ts';
import { decodeUtf8Strict, parseStrictJson, StrictJsonError } from '../../src/lib/case-package/strict-json.ts';
import { writePackageDir } from '../../src/lib/case-package/writer.ts';
import { buildSynth, type Built } from './fixtures/build.ts';
import { cleanup, tempDir } from './fixtures/synth.ts';
import {
  BAD_UTF8, DIR_CASES, EXPORT_TABLE, HOSTILE_HREFS, htmlProblems, JSON_TABLE, LINK_TABLE, ORIGINAL_CASES, PACKAGE_CASES, PATH_TABLE,
  RENDER_EXACT, RENDER_PAYLOADS, SECRET, SERVE_TABLE, SNIFF_TABLE, ZIP_CASES, type OrigCase,
} from './hostile/cases.ts';

let base: Built;
/** codes of the valid synthetic package (its known quality warnings) */
let baseline: ImportResult;
beforeAll(async () => {
  base = await buildSynth('hostile');
  baseline = await importCandidate({ files: base.files }, base.caseDir);
});
afterAll(async () => { if (base) await cleanup(base.root); });

// per-describe assertion totals (print with HOSTILE_SUMMARY=1)
const totals = new Map<string, number>();
afterEach(() => {
  const s = expect.getState();
  const top = (s.currentTestName ?? '').split(' > ')[0]!;
  totals.set(top, (totals.get(top) ?? 0) + s.assertionCalls);
});
afterAll(() => {
  if (process.env.HOSTILE_SUMMARY) console.log(JSON.stringify(Object.fromEntries(totals), null, 1), [...totals.values()].reduce((a, b) => a + b, 0));
});

const codesOf = (r: ImportResult) => Object.keys(r.counts) as Code[];
const errorsOf = (r: ImportResult) => codesOf(r).filter((c) => CODES[c].severity === 'error');

function expectOutcome(r: ImportResult, verdict: string, codes: Code[], opts: { only?: boolean; absent?: Code[]; subject?: string } = {}): void {
  const seen = codesOf(r);
  expect({ verdict: r.verdict, codes: seen }).toMatchObject({ verdict });
  if (verdict === 'reject') expect(r.candidate).toBeNull();
  else { expect(r.candidate).not.toBeNull(); expect(errorsOf(r)).toEqual([]); }
  for (const c of codes) expect(seen, `expected ${c}`).toContain(c);
  if (opts.only) {
    // the hostile property adds exactly these codes: errors are exactly `codes`, nothing new beyond them
    expect(errorsOf(r).sort()).toEqual(codes.filter((c) => CODES[c].severity === 'error').sort());
    expect(seen.filter((c) => !codes.includes(c) && !(c in baseline.counts))).toEqual([]);
  }
  for (const c of opts.absent ?? []) expect(seen, `unexpected ${c}`).not.toContain(c);
  if (opts.subject !== undefined) expect(r.diagnostics.map((d) => d.subject)).toContain(opts.subject);
}

/** Every entry under `dir` without following links or opening anything: path, type, size, mtime. */
async function tree(dir: string): Promise<string[]> {
  const out: string[] = [];
  const walk = async (rel: Buffer) => {
    const at = (r: Buffer) => Buffer.concat([Buffer.from(dir + path.sep), r]);
    const names = await readdir(at(rel), { encoding: 'buffer' }).catch(() => [] as Buffer[]);
    for (const n of names.sort(Buffer.compare)) {
      const r = rel.length ? Buffer.concat([rel, Buffer.from('/'), n]) : n;
      const s = await lstat(at(r));
      const t = s.isSymbolicLink() ? 'l' : s.isDirectory() ? 'd' : s.isFile() ? 'f' : 'x';
      out.push(`${r.toString('hex')}|${t}|${s.size}|${s.mtimeMs}|${s.ino}`);
      if (t === 'd') await walk(r);
    }
  };
  await walk(Buffer.alloc(0));
  return out;
}

// ---- package cases ----------------------------------------------------------------------------

for (const [category, cases] of Object.entries(PACKAGE_CASES)) {
  describe(category, () => {
    for (const c of cases) {
      it(`${c.id}: ${c.threat}`, async () => {
        const files = c.make(base.files);
        const before = await tree(base.caseDir);
        const r = await importCandidate({ files: files as never }, base.caseDir, { limits: c.limits as Partial<Limits> | undefined });
        expectOutcome(r, c.verdict, c.codes, { only: c.only, subject: c.subject });
        expect(await tree(base.caseDir)).toEqual(before);
        if (category === 'schema-version' && c.codes[0] === 'VER_UNSUPPORTED') expect(r.diagnostics).toHaveLength(1);
        if (category === 'json-proto') {
          expect(({} as Record<string, unknown>).polluted).toBeUndefined();
          expect(Object.prototype).not.toHaveProperty('polluted');
          if (r.candidate) {
            const row = (r.candidate.dataset('witnesses')!.data as Record<string, unknown>[])[0]!;
            expect(Object.getPrototypeOf(row)).toBe(Object.prototype);
            expect(Object.keys(row)).toContain(c.subject!);
          }
        }
      });
    }
  });
}

describe('json-nul', () => {
  it('NUL text is kept whole and rendered visibly', () => {
    expect(renderNarrative('before\u0000after', { resolveCitationHref: () => null })).toBe('<p>before⟨U+0000⟩after</p>');
  });
});

describe('citation-graph', () => {
  it('a 3,000-row citation ring validates in bounded time', async () => {
    const ring = PACKAGE_CASES['citation-graph']!.find((c) => c.id === 'ring-3000')!;
    const t0 = Date.now();
    const r = await importCandidate({ files: ring.make(base.files) as never }, base.caseDir);
    expect(Date.now() - t0).toBeLessThan(10_000);
    expect(r.counts.CITE_UNRESOLVED).toBe(baseline.counts.CITE_UNRESOLVED);
  });
});

// ---- originals in the case folder -------------------------------------------------------------

async function runOriginal(c: OrigCase): Promise<void> {
  const root = await tempDir('hostile-orig');
  try {
    const caseDir = path.join(root, 'case');
    const outside = path.join(root, 'outside');
    await cp(base.caseDir, caseDir, { recursive: true });
    await mkdir(outside);
    await writeFile(path.join(outside, 'secret.txt'), SECRET);
    const ctx = { root, caseDir, outside, base: base.files };
    const files = await c.setup(ctx);
    const folder = c.folder ? c.folder(ctx) : caseDir;
    const before = [await tree(caseDir), await tree(outside), await tree(root)];
    const r = await importCandidate({ files }, folder);
    expect([await tree(caseDir), await tree(outside), await tree(root)]).toEqual(before);
    expectOutcome(r, c.verdict, c.codes, { absent: c.absent });
    for (const [ref, p] of Object.entries(c.mapping ?? {})) {
      const m = r.candidate?.original(ref) ?? null;
      if (p === null) expect(m, `${ref} must not be mapped`).toBeNull();
      else {
        expect(m?.path, `${ref} mapping`).toBe(p);
        expect(m!.status).toBe(codesOf(r).includes('ORIG_CASE_MISMATCH') && c.codes.includes('ORIG_CASE_MISMATCH') ? 'case-mismatch' : 'verified');
      }
    }
    for (const [ref, d] of Object.entries(c.downloadOnly ?? {})) expect(r.candidate!.original(ref)!.downloadOnly).toBe(d);
    for (const ref of c.unavailable ?? []) expect(r.candidate!.isUnavailable(ref)).toBe(true);
  } finally {
    await cleanup(root);
  }
}

for (const [category, cases] of Object.entries(ORIGINAL_CASES)) {
  describe(category, () => {
    for (const c of cases) it(`${c.id}: ${c.threat}`, () => runOriginal(c));
  });
}

describe('active-content', () => {
  it.each(SERVE_TABLE)('servePolicy(%s, %s, mismatch=%s) -> %s', (mediaType, name, mismatch, mode, type) => {
    const p = servePolicy(mediaType, name, mismatch);
    expect(p.mode).toBe(mode);
    expect(p.headers['Content-Type']).toBe(type);
    expect(p.headers['X-Content-Type-Options']).toBe('nosniff');
    expect(p.headers['Content-Type']).not.toMatch(/html|svg|xml|javascript/);
    expect(p.headers['Content-Security-Policy']).toMatch(/default-src 'none'/);
    if (mode === 'download') expect(p.headers['Content-Disposition']).toMatch(/^attachment;/);
    if (mode !== 'inline-isolated' || type !== 'application/pdf') expect(p.headers['Content-Security-Policy']).toMatch(/^sandbox;/);
  });
  it.each(SNIFF_TABLE)('contentContradictsType: %s', (_label, mediaType, head, want) => {
    const bytes = typeof head === 'string' ? new TextEncoder().encode(head) : Uint8Array.from(head);
    expect(contentContradictsType(mediaType, bytes)).toBe(want);
  });
  it('Content-Disposition never carries raw CR, LF, quotes or bidi controls', () => {
    for (const name of ['crlf\r\nSet-Cookie: x=1.pdf', 'a"b\\c.pdf', 'contract‮fdp.exe', 'x⁦y⁩.pdf', '=cmd|calc.csv']) {
      const cd = servePolicy('application/pdf', `dir/${name}`, true).headers['Content-Disposition']!;
      expect(cd).not.toMatch(/[\r\n‪-‮⁦-⁩]/);
      expect(cd.match(/filename="([^"]*)"/)![1]).toMatch(/^[\x20-\x7e]*$/);
      expect(cd).toMatch(/^attachment; filename="[^"]*"; filename\*=UTF-8''[A-Za-z0-9%._~!$&+,;=:@-]*$/);
    }
  });
});

// ---- package folder and zip transport -----------------------------------------------------------

describe('package-folder', () => {
  for (const c of DIR_CASES) {
    it(`${c.id}: ${c.threat}`, async () => {
      const root = await tempDir('hostile-dir');
      try {
        const pkgDir = path.join(root, 'pkg');
        await writePackageDir(pkgDir, base.files);
        const src = await c.setup(pkgDir, root);
        const before = [await tree(root), await tree(base.caseDir)];
        const r = await importCandidate(src, base.caseDir);
        expect([await tree(root), await tree(base.caseDir)]).toEqual(before);
        expectOutcome(r, c.verdict, c.codes);
      } finally {
        await cleanup(root);
      }
    });
  }
});

const zipCategories = [...new Set(ZIP_CASES.map((z) => z.category))];
for (const category of zipCategories) {
  describe(category, () => {
    for (const z of ZIP_CASES.filter((x) => x.category === category)) {
      it(`${z.id}: ${z.threat}`, async () => {
        const root = await tempDir('hostile-zip');
        try {
          const zip = path.join(root, 'package.zip');
          await writeFile(zip, z.bytes(base.files));
          const before = [await tree(root), await tree(base.caseDir)];
          const r = await importCandidate(zip, base.caseDir, { limits: z.limits });
          expect([await tree(root), await tree(base.caseDir)]).toEqual(before);
          expectOutcome(r, z.verdict, z.codes, { subject: z.subject });
          if (z.verdict === 'reject' && z.codes.some((c) => c.startsWith('ARC_'))) expect(errorsOf(r)).toHaveLength(1);
        } finally {
          await cleanup(root);
        }
      });
    }
  });
}

// ---- links, paths, JSON and rendering ----------------------------------------------------------

describe('link-classification', () => {
  it.each(LINK_TABLE.map(([raw, kind, scheme]) => [JSON.stringify(raw).slice(0, 70), raw, kind, scheme] as const))('classifyLink(%s)', (_label, raw, kind, scheme) => {
    const c = classifyLink(raw);
    expect(c.kind).toBe(kind);
    if (scheme !== undefined) expect((c as { scheme?: string }).scheme).toBe(scheme);
    const href = safeExternalHref(raw);
    if (kind === 'external') {
      expect(href).toMatch(/^(https:\/\/[^/@\s]+\/|mailto:)/);
    } else expect(href).toBeNull();
  });
  it('external https hrefs are canonical and show the real host', () => {
    expect(safeExternalHref('https:evil.example/x')).toBe('https://evil.example/x');
    expect(safeExternalHref('https:\\\\evil.example\\x')).toBe('https://evil.example/x');
    expect(safeExternalHref('https://exаmple.example/')).toBe('https://xn--exmple-4nf.example/');
  });
});

describe('path-rules', () => {
  it.each(PATH_TABLE.map(([p, ok, trav]) => [JSON.stringify(p).slice(0, 60), p, ok, trav] as const))('checkRelPath(%s)', (_l, p, ok, trav) => {
    const v = checkRelPath(p);
    expect(v.ok).toBe(ok);
    if (!v.ok && trav !== undefined) expect(v.traversal).toBe(trav);
  });
});

describe('strict-json', () => {
  it.each(JSON_TABLE)('%s', (_label, input, code, value) => {
    if (code === null) {
      const v = parseStrictJson(input);
      if (value !== undefined) expect(Object.is(v, value) || JSON.stringify(v) === JSON.stringify(value)).toBe(true);
    } else {
      let err: unknown = null;
      try { parseStrictJson(input); } catch (e) { err = e; }
      expect(err).toBeInstanceOf(StrictJsonError);
      expect((err as StrictJsonError).code).toBe(code);
    }
  });
  it.each(BAD_UTF8)('decodeUtf8Strict rejects %s', (_label, bytes) => {
    expect(() => decodeUtf8Strict(Uint8Array.from(bytes))).toThrow(StrictJsonError);
  });
  it('a __proto__ key is an inert own property', () => {
    const v = parseStrictJson('{"__proto__": {"polluted": 1}, "constructor": {"prototype": {"polluted": 1}}}') as Record<string, unknown>;
    expect(Object.getPrototypeOf(v)).toBe(Object.prototype);
    expect(Object.hasOwn(v, '__proto__')).toBe(true);
    expect(({} as Record<string, unknown>).polluted).toBeUndefined();
  });
});

describe('text-markup rendering', () => {
  const known = new Set(['OD-001', 'OD-002']);
  const resolve = (ref: string, page: number | null) => (known.has(ref) ? documentRoute('sha256:abc', ref, page) : null);
  it.each(RENDER_PAYLOADS.map((p) => [JSON.stringify(p).slice(0, 70), p] as const))('renders %s safely', (_l, p) => {
    const html = renderNarrative(p, { resolveCitationHref: resolve });
    expect(htmlProblems(html)).toEqual([]);
    expect(html).not.toMatch(/<(?!\/?(?:p|br|a|span)[\s>])/);
    expect(html).not.toMatch(/[‪-‮⁦-⁩​-‏﻿\u0000-\u0008\u000b-\u001f\u007f]/);
  });
  it.each(RENDER_EXACT)('renderNarrative(%j) is exact', (input, want) => {
    expect(renderNarrative(input, { resolveCitationHref: resolve })).toBe(want);
  });
  it.each(HOSTILE_HREFS.map((h) => [String(JSON.stringify(h) ?? 'undefined').slice(0, 50), h] as const))('a resolver returning %s yields a broken citation', (_l, h) => {
    const html = renderNarrative('See [[OD-001]].', { resolveCitationHref: () => h as string });
    expect(isSafeAppHref(h)).toBe(false);
    expect(html).toBe('<p>See <span class="cite-broken" title="Citation does not resolve">[[OD-001]]</span>.</p>');
  });
  it('a throwing resolver yields a broken citation', () => {
    const html = renderNarrative('[[OD-001]]', { resolveCitationHref: () => { throw new Error('boom'); } });
    expect(html).toContain('cite-broken');
    expect(html).not.toContain('<a');
  });
  it('filenames reveal hidden characters and stay bounded', () => {
    expect(displayFilename('contract‮fdp.exe')).toBe('contract⟨U+202E⟩fdp.exe');
    expect(displayFilename('rep​ort.pdf')).toBe('rep⟨U+200B⟩ort.pdf');
    expect(displayFilename('﻿bom.pdf')).toBe('⟨U+FEFF⟩bom.pdf');
    expect(displayFilename('soft­hyphen.pdf')).toBe('soft⟨U+00AD⟩hyphen.pdf');
    expect(displayFilename('x\u001b[31m.pdf')).toBe('x⟨U+001B⟩[31m.pdf');
    expect([...displayFilename('A'.repeat(300))]).toHaveLength(120);
    expect(displayText('<img src=x onerror=alert(1)>.pdf')).toBe('&lt;img src=x onerror=alert(1)&gt;.pdf');
  });
});

describe('csv-formula-injection', () => {
  it.each(EXPORT_TABLE)('exportCell(%j) -> %j', (input, want) => {
    expect(exportCell(input)).toBe(want);
  });
});
